  for (const space of localSpaces(sp)) at[space.id] = where(space, ps);
  const keys = new Set(Object.values(at).filter(key => JSON.parse(key)[1]));
  const due = new Set([...keys].filter(key => !(key in this.git)));
  for (const [id, key] of Object.entries(at)) if (this.at[id] && this.at[id] !== key && keys.has(key)) due.add(key);
  this.at = at;
  const spaceOf = {};
  for (const space of localSpaces(sp)) for (const tab of space.tabs ?? []) spaceOf[tab.id] = space;
  const busy = {};
  for (const pane of ps) {
    if (!pane.terminal || !spaceOf[pane.tab]) continue;
    busy[pane.pane] = pane.status === "working" || !(pane.program?.shell || pane.program?.agent);
    if (this.busy[pane.pane] && !busy[pane.pane]) this.sameRepo(at[spaceOf[pane.tab].id], keys).forEach(key => due.add(key));
  }
  this.busy = busy;
  if (window().active) for (const key of keys) {
    if ((this.git[key] || this.unsure.has(key)) && now - (this.checked[key] ?? 0) > FALLBACK) due.add(key);
  }
  return due;
}

